changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_match_participants_match_player
    ON match_participants (match_id, player_id);

CREATE INDEX IF NOT EXISTS idx_team_ups_accepted_owner
    ON team_ups (owner_player_id) WHERE status = 'accepted';

CREATE INDEX IF NOT EXISTS idx_team_ups_accepted_member
    ON team_ups (member_player_id) WHERE status = 'accepted';

CREATE INDEX IF NOT EXISTS idx_activities_actor_created
    ON activities (actor_player_id, created_at DESC)
    WHERE visibility = 'public';

