changeSet.sql:
DROP FUNCTION IF EXISTS fn_feed_for_player(uuid, int, int, text[], timestamptz);
CREATE OR REPLACE FUNCTION fn_feed_for_player( p_player_id uuid, p_limit int DEFAULT 20, p_offset int DEFAULT 0, p_types text[] DEFAULT NULL, p_since timestamptz DEFAULT NULL, p_scope text DEFAULT 'community' ) RETURNS TABLE ( id uuid, actor_player_id uuid, actor_club_id uuid, activity_type varchar(50), reference_type varchar(50), reference_id uuid, visibility varchar(20), metadata jsonb, created_at timestamptz, geo_score int ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH community AS ( SELECT c.player_id FROM fn_community_player_ids(p_player_id) c WHERE p_scope = 'community' AND p_player_id IS NOT NULL ), my_clubs AS ( SELECT cm.club_id FROM club_memberships cm WHERE p_scope = 'community' AND p_player_id IS NOT NULL AND cm.player_id = p_player_id AND cm.status = 'active' ), scored AS ( SELECT a.id, a.actor_player_id, a.actor_club_id, a.activity_type, a.reference_type, a.reference_id, a.visibility, a.metadata, a.created_at, COALESCE( CASE WHEN lower(btrim(COALESCE(pp.barangay, c.barangay))) = lower(btrim(v.barangay)) AND lower(btrim(COALESCE(pp.city, c.city))) = lower(btrim(v.city)) THEN 3 WHEN lower(btrim(COALESCE(pp.city, c.city))) = lower(btrim(v.city)) AND lower(btrim(COALESCE(pp.province, c.province))) = lower(btrim(v.province)) THEN 2 WHEN lower(btrim(COALESCE(pp.province, c.province))) = lower(btrim(v.province)) THEN 1 ELSE 0 END, 0 ) AS geo_score, CASE WHEN c.verification_status = 'verified' THEN 1 ELSE 0 END AS verified_score FROM activities a LEFT JOIN player_profiles pp ON pp.id = a.actor_player_id LEFT JOIN clubs c ON c.id = a.actor_club_id LEFT JOIN player_profiles v ON v.id = p_player_id WHERE a.visibility = 'public' AND (p_types IS NULL OR a.activity_type = ANY(p_types)) AND (p_since IS NULL OR a.created_at > p_since) -- The scope filter. 'geo' keeps 039's behaviour for any -- caller that still wants the whole public firehose; -- 'community' is the default and what the feed sends. AND ( p_scope <> 'community' OR a.actor_player_id IN (SELECT player_id FROM community) OR a.actor_club_id IN (SELECT club_id FROM my_clubs) ) ) SELECT id, actor_player_id, actor_club_id, activity_type, reference_type, reference_id, visibility, metadata, created_at, geo_score FROM scored ORDER BY geo_score DESC, verified_score DESC, created_at DESC LIMIT p_limit OFFSET p_offset; $$;
GRANT EXECUTE ON FUNCTION fn_feed_for_player(uuid, int, int, text[], timestamptz, text) TO authenticated, anon;

